export async function fetchApiGmPoolYieldPnl(ctx, params) {
    return ctx.api.fetchJson("/v1/yield/gm-pools", {
        query: {
            period: params?.period,
            pools: params?.pools,
            includeComponents: params?.includeComponents,
        },
    });
}
export async function fetchApiGmUserEarnings(ctx, params) {
    return ctx.api.fetchJson("/v1/yield/gm-user-earnings", {
        query: {
            account: params.account,
        },
    });
}
